use vstd::prelude::*;
verus! {
spec fn same(x: u8, r: u8) -> bool { r == x }
fn preserve(x: u8) -> (r: u8) ensures same(x, r) { x }
}

use vstd::prelude::*;
verus! {
fn preserve(x: u8) -> (r: u8) ensures true { 0 }
}

use vstd::prelude::*;
verus! {
spec fn preserves(x: u8, r: u8) -> bool { r <= x }
fn preserve(x: u8) -> (r: u8) ensures preserves(x, r) { 0 }
}

use vstd::prelude::*;
verus! {
spec fn preserves(x: u8, r: u8) -> bool { r <= x }
